function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let validationPassed = false;
  let deploymentInProgress = false;

  // モデル一覧を取得してドロップダウンに設定
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9) || [];
      const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン).filter(v => v))];

      const selectModel = container.querySelector('#select-model');
      selectModel.innerHTML = '<option value="">-- モデルを選択してください --</option>';

      modelVersions.forEach(version => {
        const option = document.createElement('option');
        option.value = version;
        option.textContent = `モデル ${version}`;
        selectModel.appendChild(option);
      });

      currentModels = modelVersions.map(version => ({
        version,
        name: `AI需要予測モデル ${version}`,
        created: new Date().toISOString(),
        accuracy: Math.floor(Math.random() * 20) + 80 // 80-99%
      }));
    } catch (error) {
      console.error('モデル読み込みエラー:', error);
    }
  }

  // 店舗一覧を取得してチェックボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1) || [];
      currentStores = stores;

      const storeList = container.querySelector('#store-list');
      storeList.innerHTML = stores.map(store => `
        <label style="display: flex; align-items: center; gap: 8px; margin: 4px 0;">
          <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
          <span>${store.店舗名} (${store.店舗コード})</span>
        </label>
      `).join('');
    } catch (error) {
      console.error('店舗読み込みエラー:', error);
    }
  }

  // モデル選択時の詳細表示
  container.querySelector('#select-model').addEventListener('change', function() {
    const selectedVersion = this.value;
    const modelDetails = container.querySelector('#model-details');

    if (selectedVersion) {
      const model = currentModels.find(m => m.version === selectedVersion);
      if (model) {
        container.querySelector('#model-name').textContent = model.name;
        container.querySelector('#model-version').textContent = model.version;
        container.querySelector('#model-created').textContent = new Date(model.created).toLocaleString();
        container.querySelector('#model-accuracy').textContent = `${model.accuracy}%`;
        modelDetails.style.display = 'block';
      }
    } else {
      modelDetails.style.display = 'none';
    }

    // 検証結果をリセット
    validationPassed = false;
    container.querySelector('#validation-results').style.display = 'none';
    container.querySelector('#impact-analysis').style.display = 'none';
    container.querySelector('#btn-execute').disabled = true;
  });

  // 全店舗選択チェックボックス
  container.querySelector('#select-all-stores').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 適用前検証実行
  container.querySelector('#btn-validate').addEventListener('click', async function() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    const startDateTime = container.querySelector('#input-start-datetime').value;

    // バリデーション
    if (!selectedModel) {
      alert('適用対象モデルを選択してください。');
      return;
    }
    if (selectedStores.length === 0) {
      alert('適用対象店舗を選択してください。');
      return;
    }
    if (!startDateTime) {
      alert('適用開始日時を入力してください。');
      return;
    }
    if (new Date(startDateTime) < new Date()) {
      alert('適用開始日時には現在日時以降を指定してください。');
      return;
    }

    // 検証実行
    this.disabled = true;
    this.textContent = '検証中...';

    try {
      // 模擬検証処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 検証結果表示
      const validationResults = container.querySelector('#validation-results');
      const validationStatusText = container.querySelector('#validation-status-text');
      const validationDetails = container.querySelector('#validation-details');

      // ランダムで検証結果を決定（テスト用）
      const isValidationSuccess = Math.random() > 0.2; // 80%の確率で成功

      if (isValidationSuccess) {
        validationStatusText.textContent = '検証成功';
        validationStatusText.style.color = '#28a745';
        validationDetails.innerHTML = `
          <div style="color: var(--text);">
            ✓ データ品質チェック: 正常<br>
            ✓ 精度閾値チェック: 正常<br>
            ✓ 依存関係チェック: 正常<br>
            ✓ リソース使用量チェック: 正常
          </div>
        `;
        validationPassed = true;
        container.querySelector('#btn-execute').disabled = false;

        // 影響範囲表示
        container.querySelector('#impact-stores').textContent = selectedStores.length;
        container.querySelector('#impact-products').textContent = Math.floor(Math.random() * 500) + 100;
        container.querySelector('#impact-duration').textContent = `約${Math.floor(selectedStores.length * 2)}分`;
        container.querySelector('#impact-level').textContent = selectedStores.length > 10 ? '高' : selectedStores.length > 5 ? '中' : '低';
        container.querySelector('#impact-analysis').style.display = 'block';
      } else {
        validationStatusText.textContent = '検証失敗';
        validationStatusText.style.color = '#dc3545';
        validationDetails.innerHTML = `
          <div style="color: var(--text);">
            ✓ データ品質チェック: 正常<br>
            ✗ 精度閾値チェック: 閾値を下回っています<br>
            ✓ 依存関係チェック: 正常<br>
            ✓ リソース使用量チェック: 正常
          </div>
        `;
        validationPassed = false;
        container.querySelector('#btn-execute').disabled = true;
      }

      validationResults.style.display = 'block';
    } catch (error) {
      alert('検証処理中にエラーが発生しました。');
      console.error('検証エラー:', error);
    } finally {
      this.disabled = false;
      this.textContent = '適用前検証実行';
    }
  });

  // 適用実行
  container.querySelector('#btn-execute').addEventListener('click', async function() {
    if (!validationPassed) {
      alert('適用前検証が完了していません。');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    deploymentInProgress = true;
    this.disabled = true;
    container.querySelector('#btn-validate').disabled = true;

    const progressSection = container.querySelector('#progress-section');
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    const progressPercent = container.querySelector('#progress-percent');
    const logSection = container.querySelector('#log-section');
    const logContent = container.querySelector('#log-content');

    progressSection.style.display = 'block';
    logSection.style.display = 'block';

    const steps = [
      { text: 'モデル検証中...', duration: 2000 },
      { text: 'バックアップ作成中...', duration: 3000 },
      { text: 'モデルデプロイ中...', duration: 4000 },
      { text: '本番切替中...', duration: 2000 },
      { text: '動作確認中...', duration: 1000 }
    ];

    let currentProgress = 0;
    const totalSteps = steps.length;

    function addLog(message) {
      const timestamp = new Date().toLocaleTimeString();
      logContent.innerHTML += `[${timestamp}] ${message}\n`;
      logContent.scrollTop = logContent.scrollHeight;
    }

    addLog('モデル本番適用処理を開始しました。');

    try {
      for (let i = 0; i < steps.length; i++) {
        const step = steps[i];
        progressText.textContent = step.text;
        addLog(step.text);

        // 進捗バー更新
        const targetProgress = ((i + 1) / totalSteps) * 100;
        const startProgress = currentProgress;
        const progressDiff = targetProgress - startProgress;

        const startTime = Date.now();
        const updateProgress = () => {
          const elapsed = Date.now() - startTime;
          const progress = Math.min(elapsed / step.duration, 1);
          const currentValue = startProgress + (progressDiff * progress);

          progressFill.style.width = `${currentValue}%`;
          progressPercent.textContent = `${Math.floor(currentValue)}%`;

          if (progress < 1) {
            requestAnimationFrame(updateProgress);
          } else {
            currentProgress = targetProgress;
          }
        };
        updateProgress();

        await new Promise(resolve => setTimeout(resolve, step.duration));
        addLog(`${step.text} 完了`);
      }

      progressText.textContent = '適用完了';
      addLog('モデル本番適用処理が正常に完了しました。');

      // ロールバックボタンを表示
      container.querySelector('#rollback-section').style.display = 'block';

      alert('モデルの本番適用が正常に完了しました。');
    } catch (error) {
      progressText.textContent = 'エラー発生';
      addLog(`エラー: ${error.message}`);
      alert('適用処理中にシステムエラーが発生しました。管理者にお問い合わせください。');
    } finally {
      deploymentInProgress = false;
      this.disabled = false;
      container.querySelector('#btn-validate').disabled = false;
    }
  });

  // ロールバック実行
  container.querySelector('#btn-rollback').addEventListener('click', async function() {
    if (!confirm('前バージョンのモデルにロールバックしますか？\nこの操作は取り消せません。')) {
      return;
    }

    this.disabled = true;
    this.textContent = 'ロールバック中...';

    const logContent = container.querySelector('#log-content');

    function addLog(message) {
      const timestamp = new Date().toLocaleTimeString();
      logContent.innerHTML += `[${timestamp}] ${message}\n`;
      logContent.scrollTop = logContent.scrollHeight;
    }

    try {
      addLog('ロールバック処理を開始しました。');
      await new Promise(resolve => setTimeout(resolve, 3000));
      addLog('前バージョンのモデルに切り替え完了。');
      addLog('ロールバック処理が正常に完了しました。');

      alert('ロールバックが正常に完了しました。');

      // UI状態をリセット
      container.querySelector('#rollback-section').style.display = 'none';
      container.querySelector('#progress-section').style.display = 'none';
      validationPassed = false;
      container.querySelector('#btn-execute').disabled = true;
    } catch (error) {
      addLog(`ロールバックエラー: ${error.message}`);
      alert('ロールバック処理中にエラーが発生しました。');
    } finally {
      this.disabled = false;
      this.textContent = 'ロールバック実行';
    }
  });

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // 初期データ読み込み
  loadModels();
  loadStores();
}
